      invioBilancioRI: find(j.allegatoA?.semplici, 'invioBilancioRI', 'tariffa', DEFAULT_TARIFFE.allegatoA.invioBilancioRI),
      vidimLibri:      find(j.allegatoA?.semplici, 'vidimLibri',      'tariffa', DEFAULT_TARIFFE.allegatoA.vidimLibri),
