      iscrizioneINPS:  find(j.allegatoA?.semplici, 'iscrizioneINPS',  'tariffa', DEFAULT_TARIFFE.allegatoA.iscrizioneINPS),
      ravvedimenti:    find(j.allegatoA?.semplici, 'ravvedimenti',    'tariffa', DEFAULT_TARIFFE.allegatoA.ravvedimenti),
