/* TariffaBaseSelector
 * Wrapper standard per ogni Card di dichiarazione: scelta TRI-STATE tra
 * calcolo del tariffario standard e una "Tariffa Base concordata" (importo
 * annuo libero deciso dall'utente). Stato:
 *   - "" (default): nessuna delle due radio è preselezionata, il body è
 *     nascosto. L'utente DEVE fare una scelta esplicita.
 *   - "standard": si mostra il calcolo del tariffario (children).
 *   - "base": si mostra solo l'input dell'importo, sostituisce il calcolo.
 *
 * Compatibilità con calcAll: se modo == "" la voce ricade sul calcolo
 * standard (così i clienti salvati senza scelta esplicita continuano a
 * funzionare come prima).
 *
 *   - prefix: prefisso della coppia di campi nel form (es. "cu" → cuModo / cuTariffaBase)
 *   - children: contenuto originale (controllo del calcolo standard)
 */
const TariffaBaseSelector = ({ form, upd, prefix, children, baseLabel = "Importo annuo concordato (€)" }) => {
  const modo = form[`${prefix}Modo`] || "";  // "" | "standard" | "base"
  const baseVal = form[`${prefix}TariffaBase`] || "";
  return (
    <>
      <Radio value={modo}
        onChange={v => upd(`${prefix}Modo`, v)}
        options={[
          { val: "standard", label: "Tariffario standard" },
          { val: "base",     label: "Tariffa Base concordata" },
        ]}/>
      {modo === "" && (
        <div style={{ marginTop: 10, padding: "8px 12px", background: C.warnBg,
          border: `1px solid ${C.warnBorder}`, borderRadius: 6, fontSize: 12, color: C.warn }}>
          ⚠ Seleziona una delle due opzioni sopra per definire questa voce.
        </div>
      )}
      {modo === "standard" && (
        <div style={{ marginTop: 10 }}>{children}</div>
      )}
      {modo === "base" && (
        <div style={{ marginTop: 10 }}>
          <Inp label={baseLabel} value={baseVal}
            onChange={v => upd(`${prefix}TariffaBase`, v)}
            type="number" min="0" placeholder="Es. 100"/>
        </div>
      )}
    </>
  );
};

const QuadriTable = ({ defs, selected, righe, onToggle, onRiga }) => {
  // Totale progressivo delle voci selezionate (stessa formula di calcUnico)
  const totale = defs.reduce((s, q) => {
    if (!q.fixed && !selected[q.id]) return s;
    const n = q.perRiga ? (parseInt(righe[q.id]) || 1) : 1;
    return s + q.val * n;
  }, 0);
  return (
  <div style={{ border:`1px solid ${C.border}`, borderRadius:8, overflow:"hidden", marginTop:8 }}>
    {defs.map((q, i) => {
      const on = q.fixed || !!selected[q.id];
      return (
        <div key={q.id} style={{ display:"flex", alignItems:"center", gap:8, padding:"7px 10px",
          background:i%2===0?C.card:C.cardAlt,
          borderBottom:`1px solid ${C.border}` }}>
          <input type="checkbox" checked={on} disabled={q.fixed}
            onChange={()=>!q.fixed&&onToggle(q.id)} style={{ width:14, height:14 }}/>
          <span style={{ flex:1, fontSize:13, color:q.fixed?C.muted:C.text }}>{q.label}</span>
          <span style={{ fontSize:12, color:C.accent, minWidth:90, textAlign:"right" }}>
            {eur(q.val)}{q.perRiga?` /${q.unitLabel||"riga"}`:""}
          </span>
          {on && q.perRiga && (
            <input type="number" min="1" value={righe[q.id]||1}
              onChange={e=>onRiga(q.id,e.target.value)}
              style={{ ...sty.inp, width:62, textAlign:"center" }}/>
          )}
        </div>
      );
    })}
    {/* Totale progressivo — si aggiorna man mano che si selezionano le voci */}
    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center",
      padding:"9px 10px", background:C.groupHeader }}>
      <span style={{ fontSize:12, fontWeight:700, color:C.primary,
        textTransform:"uppercase", letterSpacing:"0.05em" }}>Totale voci selezionate</span>
      <span style={{ fontSize:14, fontWeight:800, color:C.accent }}>{eur(totale)}</span>
    </div>
  </div>
  );
};

/* ================================================================
   BANNER AGGIORNAMENTO TARIFFARIO
   ================================================================ */
function TariffBanner({ T, onUpdate, onOpenAudit, onReload }) {
  const [loading, setLoading] = useState(false);
  const [msg, setMsg]         = useState("");
  const ref = useRef();
  const isElectron = !!window.tariffarioAPI;

  const handleFile = file => {
    if (!file) return;
    setLoading(true); setMsg("");
    const reader = new FileReader();
    reader.onload = async e => {
      try {
        const newT = parseXLS(new Uint8Array(e.target.result));
        newT.fonte = `File XLS: ${file.name}`;
        // Conserva eventuali voci custom presenti nel tariffario corrente
        // (l'XLS non le contiene, ma l'utente potrebbe averle definite nell'editor)
        if (T.vociCustom) newT.vociCustom = T.vociCustom;
        // Salva in memoria persistente (storage legacy)
        try { await window.storage.set("tariffario_bcb", JSON.stringify(newT)); } catch (_) {}
        onUpdate(newT);
        setMsg("✓ Tariffario aggiornato (per modifiche persistenti, usa l'Editor del Tariffario)");
      } catch (err) {
        setMsg("Errore lettura file: " + err.message);
      }
      setLoading(false);
    };
    reader.readAsArrayBuffer(file);
  };

  const apriEditor = async () => {
    if (window.preventivatoreAPI?.openEditor) {
      await window.preventivatoreAPI.openEditor();
    } else {
      setMsg("L'Editor è disponibile solo nell'app desktop.");
    }
  };

  return (
    <div style={{ background:C.warnBg, border:`1px solid ${C.warnBorder}`, borderRadius:8,
      padding:"10px 14px", marginBottom:14, display:"flex", alignItems:"center",
      justifyContent:"space-between", gap:12, flexWrap:"wrap" }}>
      <div style={{ fontSize:13, color:C.warn }}>
        <strong>Tariffario attivo:</strong> {T.fonte}
        {(T.vociCustom || []).filter(v => v.attiva !== false).length > 0 && (
          <span style={{ marginLeft:10, padding:"2px 8px", background:"#7c3aed", color:"white",
            borderRadius:4, fontSize:11, fontWeight:600 }}>
            +{(T.vociCustom || []).filter(v => v.attiva !== false).length} voci custom
          </span>
        )}
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
        {msg && <span style={{ fontSize:12, color:msg.startsWith("✓")?C.success:C.danger }}>{msg}</span>}
        <input ref={ref} type="file" accept=".xls,.xlsx" style={{ display:"none" }}
          onChange={e => handleFile(e.target.files[0])}/>
        <button onClick={onOpenAudit}
          style={{ padding:"6px 12px", borderRadius:6, border:`1px solid ${C.warn}`,
            background:C.card, color:C.warn, cursor:"pointer", fontSize:13, fontWeight:600 }}>
          🔍 Verifica tariffario
        </button>
        {isElectron && (
          <>
            <button onClick={apriEditor}
              style={{ padding:"6px 12px", borderRadius:6, border:`1px solid ${C.warn}`,
                background:C.warn, color:"white", cursor:"pointer", fontSize:13, fontWeight:600 }}>
              💼 Apri Editor
            </button>
            {onReload && (
              <button onClick={onReload}
                style={{ padding:"6px 12px", borderRadius:6, border:`1px solid ${C.warn}`,
                  background:C.card, color:C.warn, cursor:"pointer", fontSize:13, fontWeight:600 }}>
                🔄 Ricarica
              </button>
            )}
          </>
        )}
        {!isElectron && (
          <button onClick={() => ref.current?.click()} disabled={loading}
            style={{ padding:"6px 12px", borderRadius:6, border:`1px solid ${C.warn}`,
              background:C.card, color:C.warn, cursor:"pointer", fontSize:13, fontWeight:600 }}>
            {loading ? "Lettura..." : "📥 Carica XLS"}
          </button>
        )}
      </div>
    </div>
  );
}

