/* ================================================================
   GESTIONE CLIENTI SALVATI (memoria persistente)
   ================================================================ */

// Campi del form che costituiscono l'anagrafica del cliente
// (esclusi i dati del documento specifico e della fatturazione/preventivo).
const CAMPI_CLIENTE = [
  "tipoCliente","ragioneSociale","nome","cognome","dataNascita","luogoNascita",
  "residenza","via","civico","cf","piva","email","pec",
  "nomeSocieta","sedeLegale","viaSocieta","civicoSocieta",
];

// Estrae un'identità univoca dal form: preferisce CF, poi P.IVA, poi nome+cognome+data.
// Due clienti sono "lo stesso" se condividono CF o P.IVA normalizzati.
function identitaCliente(form) {
  const cf    = (form.cf||"").toUpperCase().replace(/\s+/g,"");
  const piva  = (form.piva||"").replace(/\s+/g,"");
  if (cf)   return { tipo:"cf",   valore:cf };
  if (piva) return { tipo:"piva", valore:piva };
  const nome    = (form.nome||"").trim().toLowerCase();
  const cognome = (form.cognome||"").trim().toLowerCase();
  const data    = (form.dataNascita||"").trim();
  if (nome && cognome) return { tipo:"anag", valore:`${cognome}_${nome}_${data}` };
  const rag = (form.nomeSocieta || form.ragioneSociale || "").trim().toLowerCase();
  if (rag) return { tipo:"rag", valore:rag };
  return null;
}

// Chiave di storage derivata dall'identità. Deve essere stabile e senza caratteri vietati.
function chiaveCliente(form) {
  const id = identitaCliente(form);
  if (!id) return null;
  const safe = id.valore.replace(/[^a-zA-Z0-9_\-]/g,"_").slice(0,80);
  return `cliente:${id.tipo}:${safe}`;
}

// Etichetta leggibile per mostrare il cliente nella lista
function etichettaCliente(c) {
  if (c.tipoCliente === "soc_persone" || c.tipoCliente === "soc_capitali") {
    return c.nomeSocieta || c.ragioneSociale || `${c.cognome||""} ${c.nome||""}`.trim() || "(senza nome)";
  }
  return `${c.cognome||""} ${c.nome||""}`.trim() || c.ragioneSociale || "(senza nome)";
}

function sottoEtichettaCliente(c) {
  const parts = [];
  if (c.cf)   parts.push("CF " + c.cf);
  if (c.piva) parts.push("P.IVA " + c.piva);
  if (c.tipoCliente === "soc_persone")  parts.push("Società di Persone");
  if (c.tipoCliente === "soc_capitali") parts.push("Società di Capitali");
  if (c.tipoCliente === "pf")            parts.push("Persona fisica / Ditta Individuale");
  return parts.join(" · ");
}

// Determina se il form corrente corrisponde a un cliente già salvato
function trovaClienteSalvato(form, listaSalvati) {
  const id = identitaCliente(form);
  if (!id) return null;
  const key = chiaveCliente(form);
  return listaSalvati.find(c => c._key === key) || null;
}

