export default function App() {
  useGlobalStyles();
  const [T, setT]       = useState(DEFAULT_TARIFFE);
  const [step, setStep] = useState(0);
  const [form, setForm] = useState(INIT);
  const [genLoading, setGenLoading] = useState(false);
  const [docLinks, setDocLinks]     = useState(null);
  const [showAudit, setShowAudit]   = useState(false);
  const [genWarning, setGenWarning] = useState(null);

  // Tema: "light" | "dark" | "auto" (segue OS/browser)
  const [themeMode, setThemeMode] = useState("auto");
  const [osPrefersDark, setOsPrefersDark] = useState(false);
  const resolvedTheme = themeMode === "auto" ? (osPrefersDark ? "dark" : "light") : themeMode;

  // Clienti salvati: array di oggetti cliente. Caricato da memoria persistente.
  const [clientiSalvati, setClientiSalvati] = useState([]);
  const [clienteAttivoId, setClienteAttivoId] = useState(null);   // id cliente già caricato
  const [modaleSalvaApri, setModaleSalvaApri] = useState(false); // modale pre-avanti
  const [modaleRiduzioneApri, setModaleRiduzioneApri] = useState(false); // modale conferma riduzione fuori 20-50
  const [modaleChiudiApri, setModaleChiudiApri] = useState(false); // modale chiudi preventivo

  const upd = (k, v) => setForm(f => ({ ...f, [k]: v }));
  const { items, total } = useMemo(() => calcAll(form, T), [form, T]);
  // Righe del documento (con eventuali ritocchi finali di riga): stessa
  // funzione usata dalla generazione documenti, così Riepilogo e .docx
  // mostrano sempre gli stessi numeri.
  const righeInfo = useMemo(() => calcRighe(form, items), [form, items]);

  // C'è un preventivo "in corso"? (form diverso dallo stato iniziale)
  const preventivoInCorso = useMemo(
    () => JSON.stringify(form) !== JSON.stringify(INIT), [form]);

  // Riporta il preventivatore allo stato iniziale senza chiudere l'app
  const resetPreventivo = () => {
    setForm(INIT);
    setStep(0);
    setClienteAttivoId(null);
    setDocLinks(null);
    setGenWarning(null);
  };

  // Applica le CSS variables al :root al cambio tema
  useEffect(() => {
    const palette = THEMES[resolvedTheme] || THEMES.light;
    const root = document.documentElement;
    Object.entries(palette).forEach(([k, v]) => root.style.setProperty(`--c-${k}`, v));
    // Filter per il calendar picker delle <input type="date"> in dark mode
    root.style.setProperty("--c-datepicker-filter",
      resolvedTheme === "dark" ? "invert(0.85) brightness(1.1)" : "none");
    document.body.style.background = palette.bg;
    document.body.style.color = palette.text;
    document.body.style.colorScheme = resolvedTheme;
  }, [resolvedTheme]);

  // Ascolta il tema del SO per la modalità "auto"
  useEffect(() => {
    const mq = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)");
    if (!mq) return;
    const sync = () => setOsPrefersDark(!!mq.matches);
    sync();
    mq.addEventListener ? mq.addEventListener("change", sync) : mq.addListener(sync);
    return () => { mq.removeEventListener ? mq.removeEventListener("change", sync) : mq.removeListener(sync); };
  }, []);

  // Carica tema salvato
  useEffect(() => {
    (async () => {
      try {
        const saved = await window.storage.get("ui_theme");
        if (saved?.value && ["light","dark","auto"].includes(saved.value)) {
          setThemeMode(saved.value);
        }
      } catch (_) {}
    })();
  }, []);
  // Salva tema al cambio
  useEffect(() => {
    (async () => { try { await window.storage.set("ui_theme", themeMode); } catch(_){} })();
  }, [themeMode]);

  // Carica clienti salvati dalla memoria
  const reloadClienti = async () => {
    try {
      const lst = await window.storage.list("cliente:");
      if (!lst?.keys?.length) { setClientiSalvati([]); return; }
      const results = await Promise.all(lst.keys.map(async k => {
        try {
          const r = await window.storage.get(k);
          if (r?.value) return { _key: k, ...JSON.parse(r.value) };
        } catch(_) {}
        return null;
      }));
      setClientiSalvati(results.filter(Boolean).sort((a,b) => (b._updatedAt||0) - (a._updatedAt||0)));
    } catch (_) { setClientiSalvati([]); }
  };
  useEffect(() => { reloadClienti(); }, []);

  const handleGeneraDocs = async () => {
    setGenLoading(true);
    setDocLinks(null);
    setGenWarning(null);
    try {
      const result = await generaDocumenti(form, items, T);
      setDocLinks(result.files);
      setGenWarning(result.warning || null);
    } catch(e) {
      alert("Errore generazione documenti:\n" + e.message);
    }
    setGenLoading(false);
  };

  // Salva il PREVENTIVO COMPLETO in memoria persistente: oltre all'anagrafica
  // (mantenuta al primo livello per le etichette della lista e per la
  // retrocompatibilità), viene salvato uno snapshot integrale del form in
  // `_form`, così il preventivo si può riaprire e modificare in ogni sua parte.
  // Ritorna true in caso di successo, false se manca l'identità minima.
  const salvaClienteCorrente = async () => {
    const key = chiaveCliente(form);
    if (!key) {
      alert("Impossibile salvare: inserire almeno nome e cognome, o Codice Fiscale, o Partita IVA.");
      return false;
    }
    const data = { _updatedAt: Date.now(), _form: { ...form } };
    for (const k of CAMPI_CLIENTE) data[k] = form[k] ?? "";
    try {
      await window.storage.set(key, JSON.stringify(data));
      await reloadClienti();
      setClienteAttivoId(key);
      return true;
    } catch(e) {
      alert("Errore nel salvataggio: " + e.message);
      return false;
    }
  };

  // Carica un preventivo salvato nel form corrente.
  // - Salvataggi nuovi (con `_form`): ripristina TUTTO lo snapshot (steps 1-5),
  //   sopra INIT così i campi introdotti dopo il salvataggio hanno il default.
  // - Salvataggi vecchi (solo anagrafica): comportamento storico — carica i
  //   campi anagrafici e azzera i campi documento.
  const caricaCliente = (cliente) => {
    if (cliente._form && typeof cliente._form === "object") {
      setForm({ ...INIT, ...cliente._form });
    } else {
      const patch = {};
      for (const k of CAMPI_CLIENTE) patch[k] = cliente[k] ?? "";
      patch.dataDocumento = "";
      patch.note = "";
      patch.hasTariffaApertura = false;
      patch.tariffaApertura = "";
      setForm(f => ({ ...f, ...patch }));
    }
    setClienteAttivoId(cliente._key);
  };

  // Elimina un cliente salvato
  const eliminaCliente = async (cliente) => {
    if (!confirm(`Eliminare dalla memoria il cliente "${etichettaCliente(cliente)}"? L'operazione non è reversibile.`)) return;
    try {
      await window.storage.delete(cliente._key);
      await reloadClienti();
      if (clienteAttivoId === cliente._key) setClienteAttivoId(null);
    } catch(e) {
      alert("Errore nell'eliminazione: " + e.message);
    }
  };

  // Se l'utente modifica il preventivo dopo averlo caricato/salvato, azzeriamo
  // l'ID attivo perché i dati in memoria non corrispondono più.
  // Con lo snapshot completo il confronto copre tutti gli step, non solo
  // l'anagrafica; per i salvataggi vecchi (senza _form) resta il confronto
  // sui soli campi anagrafici.
  useEffect(() => {
    if (!clienteAttivoId) return;
    const corrente = clientiSalvati.find(c => c._key === clienteAttivoId);
    if (!corrente) { setClienteAttivoId(null); return; }
    if (corrente._form && typeof corrente._form === "object") {
      const salvato = JSON.stringify({ ...INIT, ...corrente._form });
      if (salvato !== JSON.stringify(form)) setClienteAttivoId(null);
      return;
    }
    for (const k of CAMPI_CLIENTE) {
      if ((corrente[k] ?? "") !== (form[k] ?? "")) {
        setClienteAttivoId(null);
        return;
      }
    }
  }, [form, clientiSalvati, clienteAttivoId]);

  // Gestione pulsante "Avanti" da Step 1: chiede se salvare solo se il cliente
  // non è già in memoria. Negli altri step avanza direttamente, eccetto lo Step 3
  // (Bilancio & Extra) → 4 (Riepilogo) dove chiede conferma se la percentuale di
  // riduzione per società immobiliari è fuori dal range 20-50% raccomandato.
  const clicAvanti = () => {
    // Step 3 → 4: verifica range riduzione immobiliare
    if (step === 3 && form.hasBilancio && form.bilancioImmobiliare) {
      const p = parseFloat(form.bilancioRiduzione);
      if (!isNaN(p) && (p < 20 || p > 50)) {
        setModaleRiduzioneApri(true);
        return;
      }
    }
    // Step 3 → 4: verifica Consulenza oltre soglia massima scaglioni (38,7M€).
    // Per ricavi oltre €38.734.267,42 il tariffario non prevede importo fisso:
    // l'utente deve aver inserito manualmente l'importo concordato.
    if (step === 3 && form.hasConsulenza && form.consulenzaModo !== "base") {
      const r = parseNum(form.consulenzaRicavi);
      const sogliaMax = T.consulenza[T.consulenza.length - 2].max; // 38.734.267,42
      if (r > sogliaMax && parseNum(form.consulenzaImportoManuale) <= 0) {
        alert("Per ricavi oltre €38.734.267,42 la Consulenza non rientra nelle fasce standard. Inserisci l'importo concordato nella card Consulenza prima di procedere.");
        return;
      }
    }
    if (step !== 0) {
      setStep(s => Math.min(STEPS.length-1, s+1));
      return;
    }
    // Su Step 1: verifica se il cliente è "salvabile" (ha identità minima)
    // e non è già salvato
    const id = identitaCliente(form);
    const giaSalvato = trovaClienteSalvato(form, clientiSalvati);
    if (id && !giaSalvato) {
      setModaleSalvaApri(true);
    } else {
      setStep(1);
    }
  };

  // Carica il tariffario salvato (priorità: editor JSON → storage legacy).
  // JSZip è importato staticamente dal bundle: la generazione documenti
  // funziona anche senza connessione internet.
  useEffect(() => {
    (async () => {
      try {
        // 1) Priorità: tariffario JSON dell'editor (Electron app)
        if (window.tariffarioAPI) {
          const r = await window.tariffarioAPI.read();
          if (r?.ok && r.data) {
            const internal = editorJsonToInternal(r.data);
            setT(internal);
            return;
          }
        }
        // 2) Fallback legacy: vecchio caricamento via storage (compatibilità web)
        const saved = await window.storage.get("tariffario_bcb");
        if (saved?.value) {
          const parsed = JSON.parse(saved.value);
          if (parsed && parsed.contabilita) setT(parsed);
        }
      } catch (_) {}
    })();
  }, []);

  // Quando cambia tipo cliente o regime, disattiva automaticamente gli adempimenti
  // non più applicabili (es. se si passa da Srl a forfettario, deseleziona bilancio/USC/LIPE)
  useEffect(() => {
    const elig = eleggibilita(form);
    const patch = {};
    if (!elig.upf      && form.hasUPF)      patch.hasUPF = false;
    if (!elig.usp      && form.hasUSP)      patch.hasUSP = false;
    if (!elig.usc      && form.hasUSC)      patch.hasUSC = false;
    if (!elig.bilancio && form.hasBilancio) patch.hasBilancio = false;
    if (!elig.lipe     && form.hasLipe)     patch.hasLipe = false;
    if (!elig.lipe     && form.hasLipeGruppo) patch.hasLipeGruppo = false;
    if (!elig.dichIVA  && form.hasDichIVA)  patch.hasDichIVA = false;
    // 770 è override-abile, quindi NON lo deseleziono automaticamente
    if (Object.keys(patch).length) {
      setForm(f => ({ ...f, ...patch }));
    }
  }, [form.tipoCliente, form.regimeContabile, form.hasContabilita]);

  // Auto-popolamento Ricavi della Consulenza dai Ricavi del Bilancio.
  // Si applica solo quando la Consulenza è attiva, il Bilancio ha già un valore di
  // Ricavi inserito, e il campo Ricavi della Consulenza è ancora vuoto (per non
  // sovrascrivere un valore che l'utente ha già inserito manualmente).
  useEffect(() => {
    if (form.hasConsulenza && form.hasBilancio
        && form.bilancioRicavi && !form.consulenzaRicavi) {
      setForm(f => ({ ...f, consulenzaRicavi: form.bilancioRicavi }));
    }
  }, [form.hasConsulenza, form.hasBilancio, form.bilancioRicavi]);

  // Reset dei link ai documenti generati ogni volta che si entra nello step
  // "Riepilogo". Senza questo, navigando tra gli step si potrebbero vedere link
  // vecchi che puntano ai documenti del cliente precedente.
  useEffect(() => {
    if (step === 4) {
      setDocLinks(null);
      setGenWarning(null);
    }
  }, [step]);

  const handleUpdate = newT => setT(newT);

  // Ricarica il tariffario dall'editor (utile dopo che l'utente ha salvato modifiche
  // nell'editor in un'altra finestra: clicca "Ricarica" nel preventivatore per applicarle)
  const handleReloadTariffario = useCallback(async () => {
    if (!window.tariffarioAPI) return;
    try {
      const r = await window.tariffarioAPI.read();
      if (r?.ok && r.data) {
        const internal = editorJsonToInternal(r.data);
        setT(internal);
      }
    } catch (e) {
      console.error("Errore ricarica tariffario:", e);
    }
  }, []);

  return (
    <div style={{ minHeight:"100vh", background:C.bg,
      fontFamily:"'Inter', 'Segoe UI', Arial, sans-serif" }}>

      {/* HEADER */}
      <div style={{
        background:C.headerBg, color:C.headerText,
        padding:"12px 24px", display:"flex", justifyContent:"space-between",
        alignItems:"center", gap:16,
        borderBottom:`1px solid ${C.border}`,
        boxShadow:`0 2px 12px ${C.shadowStrong}`,
      }}>
        {/* Sinistra: logo + titolo "Preventivatore" */}
        <div style={{ display:"flex", alignItems:"center", gap:16, minWidth:0 }}>
          <LogoBCB height={44}/>
          <div style={{ width:1, height:34, background:C.headerSubtle, opacity:0.35, flexShrink:0 }}/>
          <div style={{
            fontFamily:"'Space Grotesk', 'Inter', sans-serif",
            fontWeight:700, fontSize:26, letterSpacing:"-0.02em",
            color:C.headerText, lineHeight:1,
            textShadow:`0 1px 2px ${C.shadowStrong}`,
          }}>
            Preventivatore
            <div style={{ fontFamily:"'Inter', sans-serif", fontSize:11,
              fontWeight:500, color:C.headerSubtle, letterSpacing:"0.06em",
              textTransform:"uppercase", marginTop:4, textShadow:"none" }}>
              Studio Commercialista BCB
            </div>
          </div>
        </div>

        {/* Destra: totale + chiudi preventivo + toggle tema */}
        <div style={{ display:"flex", alignItems:"center", gap:12, flexShrink:0 }}>
          {righeInfo.cTot > 0 && (
            <div style={{ textAlign:"right",
              background:"rgba(255,255,255,0.08)",
              border:`1px solid rgba(255,255,255,0.12)`,
              padding:"7px 14px", borderRadius:8 }}>
              <div style={{ fontSize:10, color:C.headerSubtle,
                textTransform:"uppercase", letterSpacing:"0.06em", fontWeight:600 }}>
                Totale stimato (+IVA)
              </div>
              <div style={{ fontWeight:800, fontSize:19,
                fontFamily:"'Space Grotesk', 'Inter', sans-serif" }}>
                {eur(righeInfo.cTot)}
              </div>
            </div>
          )}
          {preventivoInCorso && (
            <button onClick={() => setModaleChiudiApri(true)}
              title="Chiudi il preventivo in corso (l'app resta aperta)"
              style={{ padding:"9px 14px", borderRadius:8,
                background:"rgba(255,255,255,0.08)",
                border:"1px solid rgba(255,255,255,0.25)",
                color:C.headerText, cursor:"pointer", fontWeight:600, fontSize:13,
                display:"flex", alignItems:"center", gap:6 }}>
              <span>✕</span><span>Chiudi preventivo</span>
            </button>
          )}
          <ThemeToggle mode={themeMode} onChange={setThemeMode}/>
        </div>
      </div>

      {/* STEP TABS — navigazione bidirezionale: ogni step è cliccabile in
          qualsiasi direzione (avanti e indietro). I dati di un eventuale step
          successivo restano comunque salvati nel form se l'utente è già
          stato lì in precedenza. */}
      <div style={{ background:C.tabs, display:"flex", boxShadow:`0 1px 4px ${C.tabsShadow}` }}>
        {STEPS.map((label, i) => (
          <button key={i} onClick={() => setStep(i)} style={{
            flex:1, padding:"10px 4px", border:"none", background:"none",
            cursor:"pointer",
            borderBottom:i===step?`3px solid ${C.accent}`:"3px solid transparent",
            color:i===step?C.accent:C.primary,
            fontWeight:i===step?700:400, fontSize:13 }}>
            <div style={{ fontSize:10, marginBottom:2, opacity:0.65 }}>{i+1}</div>
            {label}
          </button>
        ))}
      </div>

      {/* CONTENUTO */}
      <div style={{ maxWidth:800, margin:"0 auto", padding:"20px 16px 32px" }}>

        {/* Banner sempre visibile per aggiornare il tariffario */}
        <TariffBanner T={T} onUpdate={handleUpdate}
          onOpenAudit={() => setShowAudit(true)}
          onReload={handleReloadTariffario}/>

        {showAudit && <AuditPanel T={T} onClose={() => setShowAudit(false)}/>}

        {step===0 && <Step1 form={form} upd={upd}
          clientiSalvati={clientiSalvati}
          clienteAttivoId={clienteAttivoId}
          onCaricaCliente={caricaCliente}
          onEliminaCliente={eliminaCliente}
          onSalvaCliente={salvaClienteCorrente}/>}
        {step===1 && <Step2 form={form} upd={upd} T={T}/>}
        {step===2 && <Step3 form={form} upd={upd} T={T}/>}
        {step===3 && <Step4 form={form} upd={upd} T={T}/>}
        {step===4 && <Step5 items={items} total={total} form={form} upd={upd} T={T}
          righeInfo={righeInfo}
          onReset={resetPreventivo}
          onSalva={salvaClienteCorrente}
          salvato={!!clienteAttivoId}
          onGeneraDocs={handleGeneraDocs} genLoading={genLoading} docLinks={docLinks} genWarning={genWarning}/>}

        {/* NAVIGAZIONE */}
        <div style={{ display:"flex", justifyContent:"space-between", marginTop:16 }}>
          <button onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}
            style={{ padding:"10px 22px", borderRadius:6, border:`1px solid ${C.border}`,
              background:C.card, color:step===0?C.disabled:C.text,
              cursor:step===0?"not-allowed":"pointer", fontWeight:600, fontSize:14 }}>
            ← Indietro
          </button>
          {step < STEPS.length-1 && (
            <button onClick={clicAvanti}
              style={{ padding:"10px 22px", borderRadius:6, border:"none",
                background:C.accent, color:"white", cursor:"pointer",
                fontWeight:700, fontSize:14, boxShadow:"0 2px 6px rgba(37,99,168,0.3)" }}>
              {step===STEPS.length-2?"Vedi Riepilogo →":"Avanti →"}
            </button>
          )}
        </div>
      </div>

      {/* Modale pre-avanti: chiede se salvare il cliente inserito */}
      {modaleSalvaApri && (
        <ModaleConfermaSalva
          onSi={async () => {
            const ok = await salvaClienteCorrente();
            setModaleSalvaApri(false);
            if (ok !== false) setStep(1);
          }}
          onNo={() => { setModaleSalvaApri(false); setStep(1); }}/>
      )}

      {/* Modale conferma: percentuale riduzione immobiliare fuori range 20-50% */}
      {modaleRiduzioneApri && (
        <ModaleConfermaRiduzione
          percentuale={parseFloat(form.bilancioRiduzione) || 0}
          onSi={() => {
            setModaleRiduzioneApri(false);
            setStep(s => Math.min(STEPS.length-1, s+1));
          }}
          onNo={() => setModaleRiduzioneApri(false)}/>
      )}

      {/* Modale chiudi preventivo: salva e chiudi / chiudi senza salvare / annulla */}
      {modaleChiudiApri && (
        <ModaleChiudiPreventivo
          salvabile={!!identitaCliente(form)}
          onSalvaEChiudi={async () => {
            const ok = await salvaClienteCorrente();
            setModaleChiudiApri(false);
            if (ok !== false) resetPreventivo();
          }}
          onChiudiSenzaSalvare={() => { setModaleChiudiApri(false); resetPreventivo(); }}
          onAnnulla={() => setModaleChiudiApri(false)}/>
      )}
    </div>
  );
}

/* ================================================================
   EXPORT DI SERVIZIO — usati dai test automatici (harness Node) e
   potenzialmente da altre finestre. Non influiscono sull'app.
   ================================================================ */
export { calcAll, calcRighe, generaDocumenti, DEFAULT_TARIFFE, INIT, eleggibilita, eur, formatImportoLettere };
